function tke_matrix(array$entries,array$settings,string$title,bool$compact=false):void{$grid=[];foreach($entries as$e)$grid[$e['session']][$e['period']][$e['day']][]=$e;echo'<section class="schedule-card'.($compact?' compact':'').'"><h3>'.e($title).'</h3><div class="matrix-scroll"><table class="schedule-grid"><thead><tr><th class="period-head">Tiết</th>';foreach((array)$settings['days']as$d)echo'<th>Thứ '.e($d).'</th>';echo'</tr></thead><tbody>';foreach(['Sáng'=>(int)$settings['morning_periods'],'Chiều'=>(int)$settings['afternoon_periods']]as$session=>$max){for($p=1;$p<=$max;$p++){echo'<tr'.($p===1?' class="session-start"':'').' data-session="'.e($session).'"><th><span>'.$p.'</span><small>'.e($session).'</small></th>';foreach((array)$settings['days']as$d){$cell=(array)($grid[$session][$p][$d]??[]);echo'<td class="'.($cell?'has-lesson':'empty-slot').'">';foreach($cell as$e){$payload=e(json_encode(['id'=>$e['activity_id'],'day'=>$e['day'],'session'=>$e['session'],'period'=>$e['period'],'subject'=>$e['subject'],'classes'=>implode(' + ',$e['classes']),'teacher'=>$e['teacher'],'locked'=>!empty($e['locked'])],JSON_UNESCAPED_UNICODE));echo'<button type="button" class="lesson'.(!empty($e['locked'])?' locked':'').'" data-entry="'.$payload.'"><strong>'.e($e['subject']).'</strong><small>'.e(implode(' + ',$e['classes'])).' · '.e($e['teacher']).'</small></button>';}echo'</td>';}echo'</tr>';}}echo'</tbody></table></div></section>';}
