document.querySelectorAll('[data-step]').forEach(function(button){button.addEventListener('click',function(){var select=this.parentElement.querySelector('.entity-select'),next=select.selectedIndex+Number(this.dataset.step);if(next<0)next=select.options.length-1;if(next>=select.options.length)next=0;select.selectedIndex=next;select.form.submit();});});
document.querySelectorAll('[data-side]').forEach(function(button){button.addEventListener('click',function(){document.querySelectorAll('[data-side]').forEach(function(b){b.classList.remove('active')});this.classList.add('active');document.getElementById('sideUnplaced').classList.toggle('d-none',this.dataset.side!=='unplaced');document.getElementById('sideDiagnostics').classList.toggle('d-none',this.dataset.side!=='diagnostics');});});
var violations=document.getElementById('showViolations');if(violations)violations.addEventListener('change',function(){document.body.classList.toggle('show-violations',this.checked);});
var days=<?=json_encode(array_values($data['settings']['days']))?>,allEntries=<?=json_encode(array_values($entries),JSON_UNESCAPED_UNICODE)?>,blocked=<?=json_encode(array_values((array)($data['blocked']??[])),JSON_UNESCAPED_UNICODE)?>,selected=null;
function sameSlot(e,s){return String(e.day)===String(s.day)&&e.session===s.session&&Number(e.period)===Number(s.period)}
function overlaps(a,b){return a.teacher===b.teacher||(a.classes||[]).some(function(c){return(b.classes||[]).includes(c)})}
function isBlocked(e,s){return blocked.some(function(b){return b.teacher===e.teacher&&String(b.day)===String(s.day)&&b.session===s.session&&Number(b.period)===Number(s.period)})}
function cellSlot(cell){var row=cell.parentElement;return{day:days[cell.cellIndex-1],session:row.dataset.session,period:Number(row.querySelector('th span').textContent)}}
function conflicts(e,s,ignore){return allEntries.filter(function(x){return!ignore.includes(x.activity_id)&&sameSlot(x,s)&&overlaps(e,x)})}
function clearTargets(){document.querySelectorAll('.schedule-grid td').forEach(function(c){c.classList.remove('move-ok','swap-ok','move-no');delete c.dataset.action;delete c.dataset.targetId});document.querySelectorAll('.lesson.selected').forEach(function(x){x.classList.remove('selected')})}
function markTargets(e,button){clearTargets();selected=e;button.classList.add('selected');document.querySelectorAll('.schedule-grid td').forEach(function(cell){var target=cellSlot(cell),hits=conflicts(e,target,[e.activity_id]);if(isBlocked(e,target)){cell.classList.add('move-no');return}if(hits.length===0){cell.classList.add('move-ok');cell.dataset.action='move';return}if(hits.length===1){var other=hits[0],source={day:e.day,session:e.session,period:Number(e.period)},otherBlocked=isBlocked(other,source),otherHits=conflicts(other,source,[e.activity_id,other.activity_id]),moveHits=conflicts(e,target,[e.activity_id,other.activity_id]);if(!otherBlocked&&!otherHits.length&&!moveHits.length){cell.classList.add('swap-ok');cell.dataset.action='swap';cell.dataset.targetId=other.activity_id;return}}cell.classList.add('move-no')})}
function postMove(cell){if(!selected||!cell.dataset.action)return;var slot=cellSlot(cell),form=document.createElement('form');form.method='post';form.action='/tkb_xep.php';var fields={csrf:'<?=e($csrf)?>',action:cell.dataset.action,return_tab:'plan',plan_id:'<?=e($plan['id']??'')?>',activity_id:selected.activity_id,day:slot.day,session:slot.session,period:slot.period,target_id:cell.dataset.targetId||''};Object.keys(fields).forEach(function(name){var input=document.createElement('input');input.type='hidden';input.name=name;input.value=fields[name];form.appendChild(input)});document.body.appendChild(form);form.submit()}
function openEditor(e){document.getElementById('entryTitle').textContent=e.subject+' · '+(e.classes||[]).join(' + ');document.getElementById('entryMeta').textContent=e.teacher;document.getElementById('entryId').value=e.activity_id;document.getElementById('lockEntryId').value=e.activity_id;document.getElementById('entryDay').value=e.day;document.getElementById('entrySession').value=e.session;document.getElementById('entryPeriod').value=e.period;document.getElementById('lockButton').textContent=e.locked?'Mở khóa tiết':'Khóa tiết';bootstrap.Modal.getOrCreateInstance(document.getElementById('entryModal')).show()}
document.querySelectorAll('.lesson').forEach(function(lesson){var e=JSON.parse(lesson.dataset.entry),full=allEntries.find(function(x){return x.activity_id===e.id})||e;lesson.draggable=!e.locked;lesson.addEventListener('click',function(){if(!e.locked)markTargets(full,this)});lesson.addEventListener('dblclick',function(){openEditor(full)});lesson.addEventListener('dragstart',function(ev){if(e.locked){ev.preventDefault();return}markTargets(full,this);this.classList.add('dragging');ev.dataTransfer.effectAllowed='move'});lesson.addEventListener('dragend',function(){this.classList.remove('dragging')})});
document.querySelectorAll('.schedule-grid td').forEach(function(cell){cell.addEventListener('dragover',function(ev){if(selected&&this.dataset.action)ev.preventDefault()});cell.addEventListener('drop',function(ev){ev.preventDefault();postMove(this)});cell.addEventListener('click',function(ev){if(selected&&this.dataset.action&&!ev.target.closest('.lesson'))postMove(this)})});
</script></body></html>
